        q=np.power(np.longdouble(V),np.longdouble(g)); z=np.longdouble(P)*np.power(np.longdouble(V),np.longdouble(g)-1)
    return q,z

def _hull(states,g):
    z=[]
    for V,P,M in states:
        Q,N=_qnv(V,P,g)
        if not(np.isnan(Q) or np.isnan(N)): z.append((Q,N,int(M),float(V),float(P)))
    z.sort(key=lambda x:(x[0],-x[1])); d=[]; bn=-np.inf
    for x in z:
        if x[1]>bn: d.append(x);bn=x[1]
    h=[]
    for x in d:
        while len(h)>=2:
            dx1=h[-1][0]-h[-2][0];dx2=x[0]-h[-1][0]
            if dx1<=0 or dx2<=0: h.pop();continue
            if (x[1]-h[-1][1])/dx2 >= (h[-1][1]-h[-2][1])/dx1: h.pop()
            else: break
        h.append(x)
    return h

def _states(v,p,a,K,limit):
    n=len(v); total=0; exact=True
    for k in range(K+1):
        total+=math.comb(n,k)
        if total>100000: exact=False;break
    if exact:
        out=[]
        def rec(start,k,V,P,M):
            out.append((V,P,M))
            if k>=K:return
            for j in range(start,n):rec(j+1,k+1,V+v[j],P+p[j]*v[j],M|(1<<j))
        rec(0,0,a,0.,0);return out
    seeds={0:(a,0.,0)}
    orders=[np.argsort(-p),np.argsort(-(p*v)),np.argsort(-v),np.argsort(v),np.argsort(-p/(1+v/(np.mean(v)+1e-300)))]
    for order in orders:
        V=a;P=0.;M=0
        for q in range(K):
            j=int(order[q]);V+=v[j];P+=p[j]*v[j];M|=1<<j;seeds[M]=(V,P,M)
    for j in range(n):seeds[1<<j]=(a+v[j],p[j]*v[j],1<<j)
    pos=v[v>0];ref=a if a>0 else (float(np.min(pos)) if len(pos) else 1.)
    eps=.007
    ds=None
    for attempt in range(6):
        ls=math.log1p(eps);lr=math.log(ref)
        def ky(V):return -1000000000 if V<=0 else int(math.floor((math.log(V)-lr)/ls))
        d=[{} for _ in range(K+1)];d[0][ky(a)]=(a,0.,0);abort=False
        for j in range(n):
            w=float(v[j]);c=float(p[j]*v[j])
            for k in range(min(K,j+1),0,-1):
                cur=d[k]
                for V,P,M in d[k-1].values():
                    vv=V+w;pp=P+c;q=ky(vv);old=cur.get(q)
                    if old is None or pp>old[1] or (pp==old[1] and vv<old[0]):cur[q]=(vv,pp,M|(1<<j))
            if sum(map(len,d))>limit:abort=True;break
        if not abort:ds=d;break
        eps*=1.7
    if ds is not None:
        for dd in ds:
            for x in dd.values():seeds[x[2]]=x
    return list(seeds.values())

def _dink(menus,v0):
    r=np.longdouble(0);old=None;ids=[]
    for it in range(100):
        ids=[];tn=np.longdouble(0);td=np.longdouble(v0)
        for h in menus:
            scores=np.fromiter((x[1]-r*x[0] for x in h),dtype=np.longdouble,count=len(h));j=int(np.argmax(scores));ids.append(j);tn+=h[j][1];td+=h[j][0]
        rr=tn/td if td>0 else np.longdouble(0)
        if ids==old or abs(rr-r)<=np.longdouble('1e-15')*max(abs(rr),np.longdouble('1e-30')):break
        old=ids;r=rr
    return [menus[i][j][2] for i,j in enumerate(ids)],rr

def _maskstate(M,v,p,a,g):
    W=0.;P=0.
    for j in range(len(v)):
        if M>>j&1:W+=float(v[j]);P+=float(v[j]*p[j])
    Q,N=_qnv(a+W,P,g);return W,P,Q,N

def _loc(masks,menus,v,p,v0,a,g,K,use_menu=True,maxpass=12):
    m,n=v.shape; masks=list(map(int,masks)); W=np.zeros(m);P=np.zeros(m);Q=np.zeros(m,dtype=np.longdouble);N=np.zeros(m,dtype=np.longdouble)
    for i in range(m):W[i],P[i],Q[i],N[i]=_maskstate(masks[i],v[i],p[i],a[i],g[i])
    TN=N.sum(dtype=np.longdouble);TD=np.longdouble(v0)+Q.sum(dtype=np.longdouble)
    for pas in range(maxpass):
        changed=False
        for i in range(m):
            C=TN-N[i];D=TD-Q[i];cur=TN/TD if TD>0 else np.longdouble(0);best=cur;BM=masks[i];bw=W[i];bp=P[i];bq=Q[i];bn=N[i]
            def consider(As,Ps,Ms):
                nonlocal best,BM,bw,bp,bq,bn
                As=np.asarray(As,float);Ps=np.asarray(Ps,float)
                with np.errstate(all='ignore'):
                    qs=np.power(As,np.longdouble(g[i]));ns=Ps.astype(np.longdouble)*np.power(As,np.longdouble(g[i])-1);rs=(C+ns)/(D+qs)
                if len(rs):
                    j=int(np.nanargmax(rs));rr=rs[j]
                    if rr>best:
                        best=rr;BM=int(Ms[j]);bw=float(As[j]-a[i]);bp=float(Ps[j]);bq=qs[j];bn=ns[j]
            if use_menu:
                h=menus[i];consider([x[3] for x in h],[x[4] for x in h],[x[2] for x in h])
            sel=[j for j in range(n) if masks[i]>>j&1];uns=[j for j in range(n) if not(masks[i]>>j&1)]
            if sel:
                ids=np.array(sel,int);consider(a[i]+W[i]-v[i,ids],P[i]-p[i,ids]*v[i,ids],[masks[i]^(1<<j) for j in sel])
            if len(sel)<K and uns:
                ids=np.array(uns,int);consider(a[i]+W[i]+v[i,ids],P[i]+p[i,ids]*v[i,ids],[masks[i]|(1<<j) for j in uns])
            if sel and uns:
                si=np.array(sel,int)[:,None];ui=np.array(uns,int)[None,:];As=a[i]+W[i]-v[i,si]+v[i,ui];Ps=P[i]-p[i,si]*v[i,si]+p[i,ui]*v[i,ui];Ms=[masks[i]^(1<<s)|(1<<u) for s in sel for u in uns];consider(As.ravel(),Ps.ravel(),Ms)
            tol=np.longdouble('2e-14')*max(abs(cur),np.longdouble('1e-30'))
            if BM!=masks[i] and best>cur+tol:
                TN=C+bn;TD=D+bq;masks[i]=BM;W[i]=bw;P[i]=bp;Q[i]=bq;N[i]=bn;changed=True
        if not changed:break
    rr=TN/TD if TD>0 else np.longdouble(0)
    return masks,rr

def testsolve(v,p,v0,a,g,cap):
 m,n=v.shape;K=n if cap is None else min(n,max(0,int(cap)));lim=max(30000,min(90000,900000//m));menus=[]
 for i in range(m):menus.append(_hull(_states(v[i],p[i],a[i],K,lim),g[i]))
